/* Synthetic host presentation gate. The AVI is generated by pytest. */
#include "movies.h"
#include "vulkan_renderer.h"
#include "display.h"
extern "C" {
#include "hw.h"
}
#include <SDL.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <vector>
static void put16(uint8_t *p,unsigned v) { p[0]=v; p[1]=v>>8; }
static void put32(uint8_t *p,unsigned v) { put16(p,v); put16(p+2,v>>16); }
int main(int argc,char **argv) {
    if (argc<4 || argc>6) return 2;
    unsigned scale=argc>=5 ? unsigned(std::atoi(argv[4])) : 4;
    unsigned msaa=argc==6 ? unsigned(std::atoi(argv[5])) : 1;
    bool rgb24=std::atoi(argv[2])!=0;
    auto *c=static_cast<cpu_t *>(std::calloc(1,sizeof(cpu_t)));
    auto *h=static_cast<hw *>(std::calloc(1,sizeof(hw)));
    c->hw=h; h->gpu=gpu_create();
    auto *g=h->gpu;
    if (!host_gpu_configure("vulkan",scale,0,msaa,nullptr,nullptr) || !host_gpu_start(g,nullptr) || !host_gpu_enabled()) return 3;
    if (!host_movies_start(argv[1],scale,argv[3])) return 4;
    host_movies_bind(c,std::atoi(argv[2])==3 ? 2 : 1);
    put32(c->ram+0x1e8000,0x27bdffe0);
    c->ram[0x1fa3ca]=1; c->ram[0x1fa3c4]=4; c->ram[0x1fa3c5]=1; put16(c->ram+0x1fa3c0,1);
    put16(c->ram+0x1fa434+6,0);
    put32(c->ram+0x1fa3e4,0x80100000);
    put16(c->ram+0x1fa3ec,rgb24 ? 24 : 16); put16(c->ram+0x1fa3ee,224);
    put16(c->ram+0x1fa3f0,0); put16(c->ram+0x1fa3f2,8);
    h->cd.data_size=2048; h->cd.data_lba=std::atoi(argv[2])==3 ? 183956 : 151222;
    std::memcpy(h->cd.data,"SMJ\1\2\11\0\0",8);
    host_movies_sector(c);
    HostMovies::Patch patch;
    bool ready=false;
    if (std::atoi(argv[2])==3) {
        // This real mapping has offset -1: guest zero has no source image.
        for (unsigned i=0;i<30;++i) {
            host_movies_decode();
            if (HostMovies::span(0,8,c->ram+0x100000,24,patch)) {
                host_movies_stop(); host_gpu_stop(); std::free(g); std::free(h); std::free(c); return 16;
            }
            SDL_Delay(10);
        }
        put16(c->ram+0x1fa434+6,1); put16(c->ram+0x1fa3c0,2);
        put16(h->cd.data+6,1); h->cd.data_lba+=10; host_movies_sector(c);
        for (unsigned i=0;i<300;++i) {
            host_movies_decode();
            if (HostMovies::span(0,8,c->ram+0x100000,24,patch)) { ready=true; break; }
            SDL_Delay(10);
        }
        if (!ready || std::abs(patch.frame->seconds)>0.001) return 17;
        host_movies_stop(); host_gpu_stop(); std::free(g); std::free(h); std::free(c);
        std::puts("{\"negative_offset_fallback\":true,\"next_timestamp_ready\":true}"); return 0;
    }
    for (unsigned i=0;i<300;++i) {
        host_movies_decode();
        if (HostMovies::span(0,8,c->ram+0x100000,rgb24 ? 24 : 16,patch)) { ready=true; break; }
        SDL_Delay(10); // Test waits for asynchronous work. Play-path code never waits.
    }
    if (!ready) {
        if (std::atoi(argv[2])!=2) return 5;
        host_movies_stop(); host_gpu_stop(); std::free(g); std::free(h); std::free(c);
        std::puts("{\"missing_falls_back\":true}"); return 0;
    }
    // Exact PTS selection across 15 Hz guest and 30 Hz source, then restart.
    for (unsigned frame:{3u,0u,5u}) {
        put16(c->ram+0x1fa434+6,frame); put16(c->ram+0x1fa3c0,frame==5 ? 0 : frame+1); put16(h->cd.data+6,frame); h->cd.data_lba=151222+frame*10; host_movies_sector(c);
        if (frame==5) put16(c->ram+0x1fa3c0,1);
        ready=false;
        for (unsigned i=0;i<300;++i) {
            host_movies_decode();
            if (HostMovies::span(0,8,c->ram+0x100000,rgb24 ? 24 : 16,patch)) { ready=true; break; }
            SDL_Delay(10);
        }
        if (!ready || std::abs(patch.frame->seconds-double(frame)/15)>0.001) return 12;
    }
    if (HostMovies::span(0,8,c->ram+0x120000,rgb24 ? 24 : 16,patch)) return 13;
    unsigned words=rgb24 ? 480 : 320, stride=rgb24 ? 24 : 16;
    std::memset(c->ram+0x100000,0,stride*224*2);
    for (unsigned x=0;x<words;x+=stride) {
        gpu_gp0(g,0xa0000000); gpu_gp0(g,(8u<<16)|x); gpu_gp0(g,(224u<<16)|stride);
        gpu_gp0_words(g,c->ram+0x100000,stride*224/2);
    }
    gpu_gp1(g,0x03000000); gpu_gp1(g,0x05000000); gpu_gp1(g,0x06000000|(2560u<<12));
    gpu_gp1(g,0x07000000|(240u<<10)); gpu_gp1(g,0x08000001|(rgb24 ? 0x10 : 0));
    if (!rgb24) {
        // A guest rectangle over the movie must win in scaled VRAM.
        gpu_gp0(g,0xe1000400); gpu_gp0(g,0xe3000000); gpu_gp0(g,0xe4000000|1023|(511u<<10));
        gpu_gp0(g,0x620000ff); gpu_gp0(g,(60u<<16)|60); gpu_gp0(g,(20u<<16)|20);
        // A field can sample the movie background as an RGB15 texture.
        gpu_gp0(g,0xe1000500); gpu_gp0(g,0x65000080); gpu_gp0(g,(234u<<16)|30);
        gpu_gp0(g,(32u<<8)|32); gpu_gp0(g,(16u<<16)|16);
    }
    const uint8_t *pixels; int w,height;
    if (!host_gpu_rgb(g,&pixels,&w,&height) || w!=int(320*scale) || height!=int(240*scale)) { std::fprintf(stderr,"dimensions %d x %d\n",w,height); return 6; }
    auto at=[&](int x,int y) { return pixels+(y*scale*w+x*scale)*3; };
    const uint8_t *background=at(30,30);
    if (background[1]<220 || background[0]>5 || background[2]>5 || at(30,200)[1]<220) return 7;
    if (rgb24) {
        if (at(30,3)[1]) return 8; // Letterbox survives.
    } else if (at(35,235)[1]<220 || at(65,65)[0]<80 || at(65,65)[0]>180 || at(65,65)[1]<80 || at(65,65)[1]>180) { std::fprintf(stderr,"overlay rgb=%u,%u,%u\n",at(65,65)[0],at(65,65)[1],at(65,65)[2]); return 9; }
    // Guest reads must still see the original black upload, not the green AVI.
    gpu_gp0(g,0xc0000000); gpu_gp0(g,(30u<<16)|30); gpu_gp0(g,(1u<<16)|2);
    if (gpu_read(g)!=0) return 10;
    // Transition out of the movie must clear high-resolution pixels as well.
    gpu_gp0(g,0x02000000); gpu_gp0(g,0); gpu_gp0(g,(240u<<16)|words);
    if (!host_gpu_rgb(g,&pixels,&w,&height) || at(30,30)[1]) return 11;
    // Once the movie closes, a reused RAM buffer is an ordinary CPU upload.
    c->ram[0x1fa3ca]=0;
    for (unsigned i=0;i<stride*224*2;++i)
        c->ram[0x100000+i]=rgb24 ? (i%3==2 ? 255 : 0) : (i%2 ? 0x7c : 0);
    gpu_gp0(g,0xa0000000); gpu_gp0(g,8u<<16); gpu_gp0(g,(224u<<16)|stride);
    gpu_gp0_words(g,c->ram+0x100000,stride*224/2);
    if (!host_gpu_rgb(g,&pixels,&w,&height) || at(8,16)[2]<220 || at(8,16)[1]>5) return 15;
    // A movie upload can still be queued when the next CPU upload overwrites it.
    auto queue_movie=[&] {
        c->ram[0x1fa3ca]=1;
        std::memset(c->ram+0x100000,0,stride*224*2);
        gpu_gp0(g,0xa0000000); gpu_gp0(g,8u<<16); gpu_gp0(g,(224u<<16)|stride);
        gpu_gp0_words(g,c->ram+0x100000,stride*224/2);
        c->ram[0x1fa3ca]=0;
    };
    queue_movie();
    for (unsigned i=0;i<stride*224*2;++i)
        c->ram[0x100000+i]=rgb24 ? (i%3==2 ? 255 : 0) : (i%2 ? 0x7c : 0);
    gpu_gp0(g,0xa0000000); gpu_gp0(g,8u<<16); gpu_gp0(g,(224u<<16)|stride);
    gpu_gp0_words(g,c->ram+0x100000,stride*224/2);
    if (!host_gpu_rgb(g,&pixels,&w,&height) || at(8,16)[2]<220 || at(8,16)[1]>5) return 18;
    queue_movie();
    gpu_gp0(g,0xa0000000); gpu_gp0(g,8u<<16); gpu_gp0(g,(1u<<16)|2);
    gpu_gp0(g,rgb24 ? 0x00ff0000 : 0x7c007c00);
    if (!host_gpu_rgb(g,&pixels,&w,&height) || at(0,8)[2]<220 || at(0,8)[1]>5) return 19;
    // A restored CPU has no observer history. Recover the consumed ring frame
    // directly from saved RAM/CD, before any new sector reaches the observer.
    c->ram[0x1fa3ca]=1;
    auto *restored=static_cast<cpu_t *>(std::malloc(sizeof(cpu_t)));
    std::memcpy(restored,c,sizeof(cpu_t));
    host_movies_restore(restored,1);
    ready=false;
    for (unsigned i=0;i<300;++i) {
        host_movies_decode();
        if (HostMovies::span(0,8,restored->ram+0x100000,stride,patch)) { ready=true; break; }
        SDL_Delay(10);
    }
    if (!ready || std::abs(patch.frame->seconds-5.0/15)>0.001) return 20;
    // Pending HD patches and dirty native rows must not leak into the restored
    // GPU, including a different pointer and RGB24 replacement markers.
    gpu_t *restored_gpu=gpu_create();
    gpu_gp1(restored_gpu,0x03000000);
    gpu_gp1(restored_gpu,0x06000000|(2560u<<12));
    gpu_gp1(restored_gpu,0x07000000|(240u<<10));
    gpu_gp1(restored_gpu,0x08000001);
    gpu_gp0(restored_gpu,0x020000ff); gpu_gp0(restored_gpu,0); gpu_gp0(restored_gpu,(240u<<16)|320);
    if (!host_gpu_resume(restored_gpu) || !host_gpu_rgb(restored_gpu,&pixels,&w,&height) ||
        pixels[(30*scale*w+30*scale)*3]<220 || pixels[(30*scale*w+30*scale)*3+1]) return 21;
    host_movies_stop(); host_gpu_stop(); std::free(restored_gpu); std::free(restored);
    std::free(g); std::free(h); std::free(c);
    std::puts("{\"replacement\":true,\"native_reads_exact\":true,\"overlay_and_transition\":true}");
    return 0;
}
